from itertools import product

def NAND(a, b):
    return 1 - (a & b)

# Every other gate, built from NAND alone
def NOT(a):    return NAND(a, a)
def AND(a, b): return NOT(NAND(a, b))
def OR(a, b):  return NAND(NOT(a), NOT(b))
def XOR(a, b):
    n = NAND(a, b)
    return NAND(NAND(a, n), NAND(b, n))

ok = all(AND(a, b) == (a & b) and OR(a, b) == (a | b) and XOR(a, b) == (a ^ b)
         for a, b in product([0, 1], repeat=2)) and NOT(0) == 1 and NOT(1) == 0
print("NOT, AND, OR and XOR built only from NAND:", "all correct" if ok else "WRONG")
